do
$$
begin

alter table candidates add column P1_SCORE numeric;
alter table candidates add column P1_NORMAL numeric;
alter table candidates add column NCCP1MARKS numeric;
alter table candidates add column PAPER1 numeric;
alter table candidates add column P2_SCORE numeric;
alter table candidates add column NCCP2MARKS numeric;
alter table candidates add column PAPER2 numeric;

end
$$

update candidates a
set a.p1_score=b.p1_score,
a.nccp1marks=b.nccp1marks,
a.paper1=b.paper1,
a.p2_score=b.p2_score,
a.nccp2marks=b.nccp2marks,
a.paper2=b.paper2,
a.rollno=b.roll
from edp_marks b where a."registrationNo"=b.regid;---22246 updates



update candidates
set cat1_app= case
when "categoryId"='8muae23b7tr9fjq' then '1'
when "categoryId"='iutdrb8dohgp1e0' then '2'
when "categoryId"='36v2ja9y23gbpg6' then '6'
when "categoryId"='utl9ry5wyezstmk' then '9'
when "categoryId"='q5rcsku4qhxqgbh' then '0'
when "categoryId"='iglzg74etjgc13o' then '12'
when "categoryId"='nheavwocv169h12' then '11'
end;


update candidates set cat1_cpo=cat1_app;
update candidates set cat1_dp=cat1_app;

update candidates set cat1_dp='6' where cat1_app='0' and "isNctCasteEWS"=true;---151
update candidates set cat1_dp='6' where cat1_app='9' and "isNctCasteUR"=true;---158

select distinct cat1_app,cat1_dp,cat1_cpo,count(*) from candidates group by cat1_app,cat1_dp,cat1_cpo;

