select * from t_sicpo2024_dv where "candidateStatus" in ('QU (Qualified)','W (With Held)')
and ("dmeStatus" in ('Fit','Temporary Unfit') or "rmeMedicalStatus" ='Fit');---14279	

update candidates set rej_prov = 'Yes' where "dv_candidateStatus" in ('QU (Qualified)','W (With Held)')
and ("dmeStatus" in ('Fit','Temporary Unfit') or "rmeMedicalStatus" ='Fit');

create table post_pref_bsf
(rollno character varying,
pref character varying,
post_eligible character varying,
dl_for_bike character varying,
doi_for_bike character varying,
dl_for_car character varying,
doi_for_car character varying
);

select * from post_pref_bsf limit 10;

alter table candidates add column post_pref_bsf character varying;
alter table candidates add column post_eligible_bsf character varying;
alter table candidates add column dl_for_bike_bsf character varying;
alter table candidates add column doi_for_bike_bsf character varying;
alter table candidates add column dl_for_car_bsf character varying;
alter table candidates add column doi_for_car_bsf character varying;

update candidates a
set a.post_pref_bsf=b.pref,
a.post_eligible_bsf=b.post_eligible,
a.dl_for_bike_bsf=b.dl_for_bike,
a.doi_for_bike_bsf=b.doi_for_bike,
a.dl_for_car_bsf=b.dl_for_car,
a.doi_for_car_bsf=b.doi_for_car
from post_pref_bsf b where 
a.rollno=b.rollno;

select a.debarred,a."registrationNo",a.rollno,a.name,b.name as d_name,a."fathersName",b."fatherName" as d_father_name,a."mothersName",b."motherName" as d_mother_name,a.dob,b.dob as d_dob,a.gender,a.cat1_app,
b."regionId",b."examId",b."examYear",b."rollNumber",b."debarredFrom",b."debarredUpto",b.reason,b."otherReason",b."createdAt",b."updatedAt"
from candidates a,debarreds b where 
b."debarredUpto" >'2025-01-01' and
b."isActive"=true and
--replace((UPPER(a.name)||UPPER(a."fathersName")||UPPER(a."mothersName")),' ','') = replace((UPPER(b.name)||UPPER(b."fatherName")||UPPER(b."motherName")),' ','')
--and a.dob=b.dob;								  
--replace ((UPPER(b.name)||UPPER(b."motherName")),' ','') = replace ((UPPER(a.name)||UPPER(a."mothersName")),' ','') and a.dob = b.dob;
 
replace ((UPPER(b.name)||UPPER(b."fatherName")),' ','') = replace ((UPPER(a.name)||UPPER(a."fathersName")),' ','') and a.dob = b.dob;


update candidates set debarred='Yes' where rollno in ('2218011025','2222000545','2215001066');

update candidates set eligible_for_dp='No',
remarks='No valid DL' where ("dv_drivingLicenseForbike"=false or "dv_drivingLicenseForCar"=false) and dv_gender='Male';---6273


