CREATE TABLE IF NOT EXISTS public.vacancy_table
(
    slno integer,
    post_name character varying COLLATE pg_catalog."default",
    post_code character varying COLLATE pg_catalog."default" NOT NULL,
    category_code character varying COLLATE pg_catalog."default" NOT NULL,
    sub_category_code character varying COLLATE pg_catalog."default" NOT NULL,
	gender character varying,
    vacancy integer,
    initial_vacancy integer,
    current integer,
    allocated integer,
    left_vacancy integer,
    min_marks double precision,
    min_paper1 double precision,
    min_paper2 double precision,
    min_marks_cand_dob date,
    max_merit integer,
    CONSTRAINT vacancy_male_pkey PRIMARY KEY (post_code, sub_category_code, category_code)
)

TABLESPACE pg_default;

